#include <SPI.h>

const int csPin = 10;

void setup() {
  pinMode(csPin, OUTPUT);
  digitalWrite(csPin, HIGH); // De-select target initially
  SPI.begin();               // Initialize SCK(13), MOSI(11), MISO(12)
  Serial.begin(9600);
}

byte exchangeData(byte regAddress, byte value) {
  digitalWrite(csPin, LOW);         // 1. Select peripheral
  SPI.transfer(regAddress);          // 2. Transmit register
  byte response = SPI.transfer(value); // 3. Full-duplex exchange
  digitalWrite(csPin, HIGH);        // 4. Release bus
  return response;
}

void loop() {
  byte resp = exchangeData(0x00, 0xFF);
  Serial.println(resp, HEX);
  delay(2000);
}
